def can_transform(n, m, a, k, b):
    # Step 1: Apply the first operation (divisible by m)
    new_a = []
    i = 0
    while i < len(a):
        if a[i] % m == 0:
            count = 0
            while i < len(a) and a[i] % m == 0:
                count += 1
                i += 1
            new_a.extend([a[i-1] // m] * count)
        else:
            new_a.append(a[i])
            i += 1

    # Step 2: Apply the second operation (group consecutive elements)
    i = 0
    while i < len(new_a):
        j = i
        while j < len(new_a) and new_a[j] == new_a[i]:
            j += 1
        if j - i >= m:
            new_a[i] *= m
            del new_a[i+1:j]
        else:
            i += 1

    # Check if new_a can be transformed into b
    if len(new_a) != k:
        return "No"
    for i in range(k):
        if new_a[i] != b[i]:
            return "No"
    return "Yes"

def main():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        a = list(map(int, input().split()))
        k = int(input())
        b = list(map(int, input().split()))
        result = can_transform(n, m, a, k, b)
        print(result)

if __name__ == "__main__":
    main()
